{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 Bucket Server Access Logging Not Enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server access logging enabled, which is a compliance requirement for financial data to track access and changes."
    },
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 Bucket Encryption Not Configured",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks explicit encryption configuration (SSE-S3 or SSE-KMS), leaving sensitive financial data unencrypted at rest by default in some contexts or violating best practices for data protection."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 Bucket Versioning Not Enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled on the S3 bucket, preventing recovery from accidental deletions or overwrites of critical financial records."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "S3 Bucket Public Access Block Not Configured",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "There is no `aws_s3_bucket_public_access_block` resource associated with this bucket. Even with `acl = private`, explicit blocking of public access is required to prevent misconfiguration risks."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "financials" {
  bucket        = "${local.resource_prefix.value}-financials"
  acl           = "private"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-financials"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_versioning" "financials" {
  bucket = aws_s3_bucket.financials.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "financials" {
  bucket = aws_s3_bucket.financials.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "financials" {
  bucket                  = aws_s3_bucket.financials.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "financials" {
  bucket        = aws_s3_bucket.financials.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

# Note: The log bucket must exist. Assuming a standard pattern for log buckets.
resource "aws_s3_bucket" "log_bucket" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"
}",
  "fix_summary": "Added resources for S3 bucket versioning, server-side encryption, public access blocking, and server access logging. Created a dedicated log bucket to satisfy the logging configuration requirements."
}
